import{_ as r,a0 as i,w as p,s as n,ao as d,I as a,x as e,a1 as s,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"谷歌会用基于信任的认证措施取代密码吗？ | LCTT x X-CMD","titleTemplate":false,"description":"谷歌会用基于信任的认证措施取代密码吗？ | LCTT (201606) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"谷歌会用基于信任的认证措施取代密码吗？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"谷歌会用基于信任的认证措施取代密码吗？ | LCTT (201606) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201606/20160605 Will Google Replace Passwords With A New Trust-Based Authentication Method","title":"谷歌会用基于信任的认证措施取代密码吗？","tag":"201606","desc":""},"relativePath":"201606/20160605 Will Google Replace Passwords With A New Trust-Based Authentication Method.md","filePath":"[post].md"}'),w={name:"201606/20160605 Will Google Replace Passwords With A New Trust-Based Authentication Method.md"};function u(m,t,T,f,g,h){const o=i("Link");return p(),n("div",null,[t[13]||(t[13]=d('<h1 id="谷歌会用基于信任的认证措施取代密码吗" tabindex="-1">谷歌会用基于信任的认证措施取代密码吗？ <a class="header-anchor" href="#谷歌会用基于信任的认证措施取代密码吗" aria-label="Permalink to “谷歌会用基于信任的认证措施取代密码吗？”">​</a></h1><p><img src="http://www.iwillfolo.com/wordpress/wp-content/uploads/2016/05/Trust-API-Google-replaces-passwords.jpg" alt=""></p><p>一个谷歌新开发的认证措施会评估你的登录有多可靠，并且基于一个“信任分（Trust Score）”认证你的登录。</p><p>这个谷歌项目的名字是 Abacus，它的目标是让你摆脱讨厌的密码记忆和输入。</p><p>在最近的 Google I/O 开发者大会上，谷歌引入了自这个雄心勃勃的项目而来的新特性，称作“<strong>Trust API</strong>”。</p><p>“如果一切进展顺利”，这个 API（Application Programming Interface，应用程序编程接口）会在年底前供安卓开发者使用。API 会利用安卓设备上不同的传感器来识别用户，并创建一个他们称之为“信任分（Trust Score）”的结果。</p><p>基于这个信任分，一个需要登录认证的应用可以验证你确实可以授权登录，从而不会提示需要密码。</p><p><img src="http://www.iwillfolo.com/wordpress/wp-content/uploads/2016/05/Abacus-to-Trust-API.jpg" alt=""></p><p><em>Abacus 到 Trust API</em></p><h3 id="需要思考的地方" tabindex="-1">需要思考的地方 <a class="header-anchor" href="#需要思考的地方" aria-label="Permalink to “需要思考的地方”">​</a></h3><p>尽管这个想法，明智的功能，听起来很棒——减轻了密码认证的负担。</p><p>但从另一面来说，这是不是谷歌又一次逼迫我们（有意或无意）为了方便使用而放弃我们的隐私？</p><p>是否值得？这取决于你的决定...</p><hr>',14)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),s(o,{href:"http://www.iwillfolo.com/will-google-replace-passwords-with-a-new-trust-based-authentication-method/"},{default:l(()=>[...t[0]||(t[0]=[e("http://www.iwillfolo.com/will-google-replace-passwords-with-a-new-trust-based-authentication-method/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=e("作者：",-1)),s(o,{href:"http://www.iwillfolo.com/"},{default:l(()=>[...t[2]||(t[2]=[e("iWillFolo",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),s(o,{href:"https://github.com/alim0x"},{default:l(()=>[...t[3]||(t[3]=[e("alim0x",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:l(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创编译，",-1)),s(o,{href:"https://linux.cn/"},{default:l(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const C=r(w,[["render",u]]);export{x as __pageData,C as default};
